style.defs:
 and are rendered through , i.e. in a
   shadow tree: a descendant combinator from outside (".lockup .lg-ring")
   never matches there, so every inner rule is a bare class (lg-*). The
   ghosts / slices / scanlines are real DOM and may use the ancestor. */
.lg-ring { fill: none; stroke: var(--toxic); stroke-width: 7; stroke-linecap: round; stroke-dasharray: 258; stroke-dashoffset: 258; animation: lg-draw .75s cubic-bezier(.2,.8,.2,1) .15s forwards; }
.lg-bolt { fill: none; stroke: var(--toxic); stroke-width: 7; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 100; stroke-dashoffset: 100; animation: lg-draw .38s cubic-bezier(.1,.9,.2,1) .8s forwards, lg-strike .6s steps(1) .8s 1; }
.lg-flash { fill: var(--toxic); opacity: 0; animation: lg-flash .55s ease-out 1.1s 1; }
.lg-word { font-family: var(--display); font-weight: 900; font-size: 96px; fill: var(--chalk); }
.lg-word tspan { opacity: 0; animation: lg-on 1ms steps(1) forwards; animation-delay: calc(1.3s + var(--i) * 85ms); }
.lg-line { font-family: var(--mono); font-size: 17px; fill: var(--toxic); }
.lg-line tspan { opacity: 0; animation: lg-on 1ms steps(1) forwards; animation-delay: calc(2.15s + var(--i) * 36ms); }
.lg-cur { fill: var(--toxic); opacity: 0; animation: lg-on 1ms steps(1) 3.35s forwards, lg-blink 1.1s steps(2, start) 3.35s infinite; }
.lockup.animated .ghost { opacity: 0; mix-blend-mode: screen; }
.lockup.animated .ghost.r { --toxic: var(--hazard); --chalk: var(--hazard); animation: lg-ghostr 5s steps(1) 3.6s infinite; }
.lockup.animated .ghost.c { --toxic: var(--signal); --chalk: var(--signal); animation: lg-ghostc 5s steps(1) 3.6s infinite; }
.lockup.animated .s1 { animation: lg-j1 5s steps(1) 3.6s infinite; }
.lockup.animated .s2 { animation: lg-j2 5s steps(1) 3.6s infinite; }
.lockup.animated .s3 { animation: lg-j3 5s steps(1) 3.6s infinite; }
.lockup.animated .scan { animation: lg-crawl .25s linear infinite; }
/* the static small lockup (real DOM text) */
.lockup.small .word { font-family: var(--display); font-weight: 900; font-size: 84px; fill: var(--chalk); }
.lockup.small .line { font-family: var(--mono); font-size: 17px; fill: var(--toxic); }
@keyframes lg-draw { to { stroke-dashoffset: 0; } }
@keyframes lg-strike { 0%, 35% { stroke: #fff; } 45% { stroke: var(--toxic); } 60% { stroke: #fff; } 70%, 100% { stroke: var(--toxic); } }
@keyframes lg-flash { 0% { opacity: .55; } 100% { opacity: 0; } }
@keyframes lg-on { to { opacity: 1; } }
@keyframes lg-blink { 50% { opacity: 0; } }
@keyframes lg-ghostr { 0%, 84% { opacity: 0; transform: translate(0, 0); } 85% { opacity: .9; transform: translate(-5px, 1px); } 87% { transform: translate(4px, -1px); } 89% { transform: translate(-3px, 2px); } 90%, 100% { opacity: 0; transform: translate(0, 0); } }
@keyframes lg-ghostc { 0%, 84% { opacity: 0; transform: translate(0, 0); } 85% { opacity: .9; transform: translate(5px, -1px); } 87% { transform: translate(-4px, 1px); } 89% { transform: translate(3px, -2px); } 90%, 100% { opacity: 0; transform: translate(0, 0); } }
@keyframes lg-j1 { 0%, 84% { transform: translate(0, 0); } 85% { transform: translate(7px, 0); } 87% { transform: translate(-4px, 0); } 89% { transform: translate(2px, 0); } 90%, 100% { transform: translate(0, 0); } }
@keyframes lg-j2 { 0%, 84% { transform: translate(0, 0); } 85% { transform: translate(-8px, 0); } 86.5% { transform: translate(5px, 0); } 88.5% { transform: translate(-3px, 0); } 90%, 100% { transform: translate(0, 0); } }
@keyframes lg-j3 { 0%, 84% { transform: translate(0, 0); } 85.5% { transform: translate(5px, 0); } 87.5% { transform: translate(-6px, 0); } 89% { transform: translate(3px, 0); } 90%, 100% { transform: translate(0, 0); } }
@keyframes lg-crawl { to { transform: translateY(3px); } }
@media (prefers-reduced-motion: reduce) {
  .lg-ring, .lg-bolt, .lg-word tspan, .lg-line tspan, .lg-cur, .lg-flash, .lockup.animated .ghost, .lockup.animated .s1, .lockup.animated .s2, .lockup.animated .s3, .lockup.animated .scan { animation: none !important; }
  .lg-ring, .lg-bolt { stroke-dashoffset: 0; }
  .lg-word tspan, .lg-line tspan, .lg-cur { opacity: 1; }
  .lg-flash { opacity: 0; }
}
